// UpdateNewValues updates the mutable fields using the new values that were set on create except the ID field.
// Using this option is equivalent to using:
//
//	client.OutboxMessage.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(outboxmessage.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *OutboxMessageUpsertOne) UpdateNewValues() *OutboxMessageUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		if _, exists := u.create.mutation.ID(); exists {
			s.SetIgnore(outboxmessage.FieldID)
		}
		if _, exists := u.create.mutation.CreatedAt(); exists {
			s.SetIgnore(outboxmessage.FieldCreatedAt)
		}
		if _, exists := u.create.mutation.SchoolID(); exists {
			s.SetIgnore(outboxmessage.FieldSchoolID)
		}
		if _, exists := u.create.mutation.Channel(); exists {
			s.SetIgnore(outboxmessage.FieldChannel)
		}
		if _, exists := u.create.mutation.TemplateKey(); exists {
			s.SetIgnore(outboxmessage.FieldTemplateKey)
		}
		if _, exists := u.create.mutation.RecipientHash(); exists {
			s.SetIgnore(outboxmessage.FieldRecipientHash)
		}
		if _, exists := u.create.mutation.RecipientHashVersion(); exists {
			s.SetIgnore(outboxmessage.FieldRecipientHashVersion)
		}
		if _, exists := u.create.mutation.RecipientRedacted(); exists {
			s.SetIgnore(outboxmessage.FieldRecipientRedacted)
		}
		if _, exists := u.create.mutation.MaxAttempts(); exists {
			s.SetIgnore(outboxmessage.FieldMaxAttempts)
		}
		if _, exists := u.create.mutation.IdempotencyKey(); exists {
			s.SetIgnore(outboxmessage.FieldIdempotencyKey)
		}
	}))
	return u
}

